new_redis = '''        // DATABASE_URL (postgres://user:pass@host:port/db) is used when set, e.g. on Render;
        // otherwise fall back to the docker compose defaults.
        private static string GetPostgresConnectionString()
        {
            var url = Environment.GetEnvironmentVariable("DATABASE_URL");
            if (string.IsNullOrEmpty(url))
            {
                return "Server=db;Username=postgres;Password=postgres;";
            }

            var uri = new Uri(url);
            var userInfo = uri.UserInfo.Split(':', 2);
            var builder = new NpgsqlConnectionStringBuilder
            {
                Host = uri.Host,
                Port = uri.Port > 0 ? uri.Port : 5432,
                Username = Uri.UnescapeDataString(userInfo[0]),
                Database = Uri.UnescapeDataString(uri.AbsolutePath.TrimStart('/')),
            };
            if (userInfo.Length > 1)
            {
                builder.Password = Uri.UnescapeDataString(userInfo[1]);
            }
            return builder.ConnectionString;
        }

        // REDIS_URL (redis://[user:pass@]host:port or rediss://...) is used when set;
        // otherwise fall back to the docker compose host "redis".
        private static ConnectionMultiplexer OpenRedisConnection()
        {
            var hostname = "redis";
            var port = 6379;
            string password = null;
            var ssl = false;

            var url = Environment.GetEnvironmentVariable("REDIS_URL");
            if (!string.IsNullOrEmpty(url))
            {
                var uri = new Uri(url);
                hostname = uri.Host;
                if (uri.Port > 0)
                {
                    port = uri.Port;
                }
                ssl = uri.Scheme == "rediss";
                if (!string.IsNullOrEmpty(uri.UserInfo))
                {
                    var userInfo = uri.UserInfo.Split(':', 2);
                    password = Uri.UnescapeDataString(userInfo[userInfo.Length - 1]);
                }
            }

            // Use IP address to workaround https://github.com/StackExchange/StackExchange.Redis/issues/410
            var ipAddress = GetIp(hostname);
            Console.WriteLine($"Found redis at {ipAddress}");

            var options = new ConfigurationOptions
            {
                Password = password,
                Ssl = ssl,
                SslHost = ssl ? hostname : null,
            };
            options.EndPoints.Add(ipAddress, port);

            while (true)
            {
                try
                {
                    Console.Error.WriteLine("Connecting to redis");
                    return ConnectionMultiplexer.Connect(options);
                }
                catch (RedisConnectionException)
                {
                    Console.Error.WriteLine("Waiting for redis");
                    Thread.Sleep(1000);
                }
            }
        }

'''
s=s.replace(old_redis,new_redis)
